    if (!nullToAbsent || academicYearId != null) {
      map['academic_year_id'] = Variable<int>(academicYearId);
    }
    map['certificate_type'] = Variable<String>(certificateType);
    map['title'] = Variable<String>(title);
    map['issue_date'] = Variable<DateTime>(issueDate);
    map['status'] = Variable<String>(status);
    if (!nullToAbsent || reason != null) {
      map['reason'] = Variable<String>(reason);
    }
    if (!nullToAbsent || conduct != null) {
      map['conduct'] = Variable<String>(conduct);
    }
    map['dues_cleared'] = Variable<bool>(duesCleared);
    if (!nullToAbsent || remarks != null) {
      map['remarks'] = Variable<String>(remarks);
    }
    if (!nullToAbsent || issuedBy != null) {
      map['issued_by'] = Variable<String>(issuedBy);
    }
    if (!nullToAbsent || dataJson != null) {
      map['data_json'] = Variable<String>(dataJson);
    }
    map['created_at'] = Variable<DateTime>(createdAt);
    return map;
  }

  CertificatesCompanion toCompanion(bool nullToAbsent) {
    return CertificatesCompanion(
      id: Value(id),
      certificateNumber: Value(certificateNumber),
      studentId: Value(studentId),
      academicYearId:
          academicYearId == null && nullToAbsent
              ? const Value.absent()
              : Value(academicYearId),
      certificateType: Value(certificateType),
      title: Value(title),
      issueDate: Value(issueDate),
      status: Value(status),
      reason:
          reason == null && nullToAbsent ? const Value.absent() : Value(reason),
      conduct:
          conduct == null && nullToAbsent
              ? const Value.absent()
              : Value(conduct),
      duesCleared: Value(duesCleared),
      remarks:
          remarks == null && nullToAbsent
              ? const Value.absent()
              : Value(remarks),
      issuedBy:
          issuedBy == null && nullToAbsent
              ? const Value.absent()
              : Value(issuedBy),
      dataJson:
          dataJson == null && nullToAbsent
              ? const Value.absent()
              : Value(dataJson),
      createdAt: Value(createdAt),
    );
  }

